// Request VIP / 100% waiver BEFORE consultation (needs approval)  (permissions: opd.waiver.request)
export const preconsultWaiver = (ticket_id, body) =>
  api("POST", `/opd-tickets/${ticket_id}/vip-waiver-request`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Ticket with invoice, queue entry, pending approval and cash-back prompts  (permissions: opd.ticket.view, opd.queue.doctor)
export const getTicket = (ticket_id) =>
  api("GET", `/opd-tickets/${ticket_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Scan an OPD slip barcode  (permissions: opd.ticket.view)
export const byNumber = (ticket_number) =>
  api("GET", `/opd-tickets/by-number/${ticket_number}`, undefined);   // api(): see get_guide('envelope-and-errors')
